import fs from 'node:fs';
import path from 'node:path';

/** Only these trees are generated by release-native in an exclusively created staging. */
const owned = new Set(['_tar', '_rebuild', 'vendor', 'node_modules']);
export function removeGenerated(staging, target) {
  const root = path.resolve(staging);
  const dest = path.resolve(target);
  const rel = path.relative(root, dest);
  if (!rel || rel === '..' || rel.startsWith('..' + path.sep) || path.isAbsolute(rel) || !owned.has(rel.split(path.sep)[0])) {
    throw new Error('Refusing cleanup outside a generated staging child: ' + dest);
  }
  // Check every ancestor, including staging itself, and every descendant before removal.
  let cur = dest;
  while (true) {
    if (fs.existsSync(cur) && fs.lstatSync(cur).isSymbolicLink()) throw new Error('Refusing junction cleanup: ' + cur);
    const parent = path.dirname(cur);
    if (parent === cur) break;
    cur = parent;
  }
  const inspect = p => {
    const st = fs.lstatSync(p);
    if (st.isSymbolicLink()) throw new Error('Refusing junction cleanup: ' + p);
    if (st.isDirectory()) for (const name of fs.readdirSync(p)) inspect(path.join(p, name));
  };
  if (!fs.existsSync(dest)) return;
  inspect(dest);
  fs.rmSync(dest, { recursive: true, force: true });
}
